import { user } from "./user.js";

const socket = io();

const username = document.getElementById("name-input");
const messageContainer = document.getElementById("message-container");
const messageForm = document.getElementById("message-form");
const messageInput = document.getElementById("message-input");
const userForm = document.getElementById("gameForm");
const answerTone = new Audio("/answer.wav");
const questionTone = new Audio("/question.wav");

messageForm.addEventListener("submit", (e) => {
  e.preventDefault();
  sendMessage();
});

socket.on("player_joined", (data) => {
  username.innerText = `${data}`;
});

const question = document.getElementById("message-left");

socket.on("question_created", (data) => {
  question.innerHTML = `${data}`;
});

const sendMessage = () => {
  console.log(messageInput.value);

  if (messageInput.value === "") return;
  const data = {
    guess: messageInput.value,
    datetime: Date.now(),
  };

  socket.emit("guess_answer", data);
  addMessageToUI(true, data);

  messageInput.value = "";
};

socket.on("correct_answer", (data) => {
  answerTone.play();
  addMessageToUI(false, data);
});

socket.on("question_created", (question) => {
  questionTone.play();
  addMessageToUI(false, question);
});

socket.on("attempted", (data) => {
  // send as an alert to the user
});

const addMessageToUI = (isOwnedMessage, data) => {
  const element = `
        <li class="${isOwnedMessage ? "message-right" : "message-left"}">
          <p class="message" id="message-left">
            ${isOwnedMessage ? data.guess : data.message}
            <span>${isOwnedMessage ? "" : data.username} • ${moment(
    data.datetime
  ).fromNow()}</span>
          </p>
        </li>`;

  messageContainer.innerHTML += element;
  scrollToBottom();
};

const scrollToBottom = () => {
  messageContainer.scrollTo(0, messageContainer.scrollHeight);
};

const feedbackTop = (is_host, data) => {
  const element = `
        <li class="message-feedback-top">
          <p class="feedback-top" id="feedback-top">
            
          ${data} ${is_host ? "is the host" : "joined"}
          </p>
        </li>`;

  messageContainer.innerHTML += element;
};
socket.on("session_created", (data) => {
  clearTopFeedback();
  feedbackTop(true, data);
});

socket.on("player_joined", (data) => {
  clearTopFeedback();
  feedbackTop(false, data);
});
const clearTopFeedback = () => {
  document.querySelectorAll("li.message-feedback-top").forEach((element) => {
    element.parentNode.removeChild(element);
  });
};
socket.on("session_restarted", (data) => {
  feedback(data);
});

const feedback = (data) => {
  const element = `
        <li class="message-feedback-top">
          <p class="feedback-top" id="feedback-top">
            
          ${data} ${is_host ? "is the host" : "joined"}
          </p>
        </li>`;

  messageContainer.innerHTML += element;
};

socket.on("assignGameMaster", (isGameMaster) => {
  if (isGameMaster) {
    setQuestionBtn.style.display = "block";
  } else {
    setQuestionBtn.style.display = "none";
  }
});

setQuestionBtn.addEventListener("click", () => {
  document.getElementById("popover").classList.remove("hidden");
});

submitQA.addEventListener("click", () => {
  const question = questionInput.value.trim();
  const answer = answerInput.value.trim();

  if (!question || !answer) return alert("Please enter both!");

  socket.emit("set_question", { question, answer });

  // Reset fields + hide popover
  questionInput.value = "";
  answerInput.value = "";
  popover.classList.add("hidden");

  // Hide button so GM can’t set another question this round
  setQuestionBtn.style.display = "none";
});

closePopover.addEventListener("click", () => {
  popover.classList.add("hidden");
});

leave.addEventListener("click", () => {
  // e.preventDefault()
  socket.emit("disconnect");
});

socket.on("player_left", (data) => {
  feedback(data);
});

socket.on("session_deleted", (data) => {
  feedback(data);
});

const modeInputs = document.querySelectorAll("input[name='mode']");
const codeField = document.getElementById("codeField");

// Show code field only when "Join Game" is selected
modeInputs.forEach((radio) => {
  radio.addEventListener("change", () => {
    if (radio.value === "join" && radio.checked) {
      codeField.style.display = "block";
    } else {
      codeField.style.display = "none";
    }
  });
});

// Submit form
userForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const formData = new FormData(e.target);
  const data = Object.fromEntries(formData.entries());

  user(data);
});
